// ZOE product configs for the E-Systems "ess-cabinet" 3D catalog engine (same schema as the Bluesun / Elecnova catalogs).
// Dimensions and specs: zoeess.com product pages, ZOE datasheets and user manuals (zoeess.com/uploads/...),
// ZOE quotation "2.5MW-5MWH BESS Quotation.pdf" (Google Drive, ESS). Layouts: manual drawings where available, else renders.

const BRAND = 'ZOE';
const COLORS = {
  shell: '#E8EAEC', roof: '#E0E3E6', plinth: '#25282C', door: '#ECEEF0', doorIn: '#DFE3E6', frame: '#C8CDD2',
  accent: '#2E3236', module: '#D3D8DC', modFace: '#C6CCD1', hv: '#9AA3AA', pcs: '#B5BDC3', chiller: '#C0C7CC',
  dist: '#D7DCE0', inv: '#F0F2F3', cab: '#E1E5E8', coil: '#3F5566', duct: '#CBD2D6',
};
const base = (extra = {}) => ({
  template: 'ess-cabinet', brand: BRAND, theme: { brand: '#1226AA' },
  logo: { type: 'plain', text: 'ZOE', color: '#1226AA' }, colors: { ...COLORS, ...(extra.colors || {}) },
});
const eyes = (w, d) => [-1, 1].flatMap(sx => [-1, 1].map(sz => ({ type: 'eye', x: sx * (w / 2 - 0.1), z: sz * (d / 2 - 0.1) })));
const fmt = n => String(n).replace('.', ',');
const LEDS = ['#2EE07A', '#F2C230', '#E8392B'];
const SRC_SITE = id => `сторінка товару zoeess.com/en/product/${id}.html`;
const NS = 'немає в джерелі';

// ---------- common texts ----------
const CELL = (ah, series, v, extra = []) => ({ name: `Комірка LFP ${ah} А·год`, text: `Призматична комірка LFP 3,2 В. ${series} комірок послідовно дають ${v} В.`, kv: [['Ємність', `${ah} А·год`], ['Номінальна напруга', '3,2 В'], ...extra] });
const FIRE_INFO = (extra = '', agent = 'аерозоль') => ({ name: 'Пожежна безпека', short: 'Пожежогасіння', text: `Раннє попередження (дим, температура) і гасіння: ${agent}${extra}. Запустіть тест, щоб побачити спрацювання.`, kv: [['Засіб гасіння', agent], ['Датчики', 'дим, температура']] });
const EMS_INFO = { name: 'Контролер і EMS', short: 'EMS', text: 'Локальний контролер шафи збирає дані BMS, PCS, охолодження і пожежної системи; моніторинг через Web / APP. Кількома шафами і STS на об\'єкті може керувати EMS E-Systems.', kv: [['Протокол', 'Modbus TCP']] };
const estopInfo = { name: 'Аварійна кнопка', text: 'Аварійне відключення на дверях; поруч індикатор стану.', kv: [] };

function fireCab(w, d, h, extra = []) {
  return {
    items: [
      { type: 'aerosol', pos: [-w * 0.18, h - 0.22, 0.1], r: 0.05, len: 0.3, label: 'Аерозольний генератор шафи', left: true, pin: [0, 0.08, 0] },
      { type: 'smoke', pos: [w * 0.22, h - 0.12, d * 0.2], label: 'Датчик диму', pin: [0, -0.08, 0] },
      { type: 'heat', pos: [w * 0.05, h - 0.12, -d * 0.2], label: 'Датчик температури', pin: [0, -0.07, 0] },
      ...extra,
      { type: 'led', index: 2, label: 'Індикатор стану на дверях', pin: [0.05, 0.03, 0.02] },
      { type: 'estop', label: 'Аварійна кнопка', pin: [0, -0.06, 0.02] },
    ], alarmLeds: [2],
  };
}
const packAerosol = (x, y, z, label = 'Аерозоль у пакеті (опція, PACK-level)') => ({ type: 'aerosol', vertical: true, pos: [x, y, z], r: 0.03, len: 0.18, label, pin: [0.04, 0.1, 0] });
// dark vertical HMI bar of ZOE cabinets: indicator, e-stop, warning sign
const hmiBar = (x, y, h = 0.42, w = 0.075, ledsN = 2) => [
  { type: 'plate', mat: 'black', x, y, w, h },
  { type: 'leds', pts: Array.from({ length: ledsN }, (_, i) => [x, y + h * 0.3 - i * 0.07]), colors: ledsN === 3 ? LEDS : ['#2EE07A', '#E8392B'], r: 0.012 },
  { type: 'estop', small: true, x, y: y - h * 0.08 },
  { type: 'warn', x, y: y - h * 0.34, w: 0.05, h: 0.045 },
];

const usesCabinet = (kw, kwh) => {
  const h = (kwh * 0.9 / kw).toFixed(1).replace('.', ',');
  return [
    ['Peak shaving і тарифи', 'Заряд у нічний тариф або від СЕС, розряд у пікові години; EMS тримає імпорт з мережі під заданою межею.', 'b'],
    ['Резерв з STS', 'Безшовне живлення критичного навантаження (20 мс) дає шафа Z BOX-STS 250/500/800.', 'b'],
    ['Тривалість резерву', `≈ ${h} год при ${kw} кВт (90 % ємності, без урахування ККД).`, 'e'],
    ['Масштабування', 'Шафи з\'єднуються паралельно на стороні змінного струму (до 5 шаф на STS 800).', 'b'],
  ];
};

// STS + several cabinets (system tab)
const stsParts = (n, model, kw, kwh, stsName, stsText) => [
  { id: 'ess', name: `Шафи ESS 1–${n}`, text: `${n} × ${model} паралельно: ${fmt(kwh)} кВт·год і ${kw} кВт.`, kv: [['Ємність', `${n} × ${fmt(+(kwh / n).toFixed(1))} кВт·год`], ['Потужність', `${n} × ${kw / n} кВт`]] },
  { id: 'sts', name: `Шафа STS ${stsName}`, text: stsText, kv: [['Перехід', '20 мс'], ['Шаф ESS', 'STS 250: 1 · STS 500: 3 · STS 800: 5 × 125 кВт'], ['Габарит', NS]] },
  { id: 'emsS', name: 'EMS E-Systems', text: 'Керує шафами і STS: peak shaving, тарифи, резерв заряду, моніторинг.', kv: [['Зв\'язок', 'Modbus TCP']] },
  { id: 'load', name: 'Критичне навантаження', text: 'Навантаження, яке живиться через STS під час відключення мережі.', kv: [] },
  { id: 'grid', name: 'Мережа 0,4 кВ', text: 'Основне живлення об\'єкта; від мережі заряджаються шафи.', kv: [] },
];
const STS_TEXT = 'Шафа безшовного переходу ZOE для шаф 125 кВт: STS, UPS, лічильник 0,5S, автомати, SPD, ATS — опція. Перехід мережа ↔ автономія за 20 мс.';

// =====================================================================================
