// ---------------- containers ----------------
function containerCfg({ id, model, L, W = 2.438, H, kw, kwh, cols, perCol, modDims, sections, srcs, meta, page, info, summary, caption, rowsExtra = [], unitsExtra = [], chillerOutside = true, fireAgent = 'аерозоль', accuracy }) {
  const xs0 = sections.batteryX0, xs1 = sections.batteryX1;
  const cw = (xs1 - xs0) / cols;
  const columns = Array.from({ length: cols }, (_, i) => ({ x: xs0 + (i + 0.5) * cw, n: perCol }));
  const doors = []; const ndoor = sections.ndoor || Math.max(2, Math.round((xs1 - xs0) / 1.2)); const dw = (xs1 - xs0) / ndoor;
  const letters = sections.letters || [];
  for (let i = 0; i < ndoor; i++) {
    const x0 = xs0 + i * dw, x1 = x0 + dw - 0.04;
    doors.push({ hinge: i % 2 ? 'right' : 'left', x0, x1, items: [{ type: 'line', x: 0.03, y: H / 2, w: 0.05, h: H - 0.3, mat: 'accent' }, { type: 'handle', x: dw * 0.5, y: 1.1, h: 0.2 }, { type: 'warn', x: dw * 0.5, y: 0.75, w: 0.1, h: 0.09 }, ...(letters[i] ? [{ type: 'logo', x: dw * 0.5, y: H - 0.6, w: dw * 0.94, h: dw * 0.235 }] : [])] });
  }
  doors.push(...sections.extraDoors);
  return { ...base(), id, model, kw, kwh, cooling: 'liquid', accuracy: accuracy || { level: 'schematic', label: 'Габарит — з даташита ZOE, розкладка — за кресленням / рендером, схематично' }, caption,
    pullDepth: 0.85, view: { maxDist: 20 },
    cabinet: { w: L, d: W, h: H, floor: 0.15, roof: 0.08, style: 'container', frontWall: true, doorOpen: 1.5, slots: [], baseItems: [], partitions: sections.partitions, doors },
    rack: { y0: 0.4, pitch: modDims.h + 0.04, z: -0.55, columns, module: { w: Math.min(modDims.w, cw - 0.04), h: modDims.h, d: modDims.d, simple: true, label: 'ZOE', sub: modDims.sub }, explode: [0, 0.15, 0.12, 2.3] },
    units: [
      ...(chillerOutside ? [{ id: 'chiller', kind: 'acu', size: [1.6, 1.6, 0.4], pos: [-L / 2 - 0.2, 1.3, 0], mat: 'chiller', rotY: -90, outside: true, fixed: true, mount: 'left', pull: [0, 0, 0], explode: [-0.9, 0, 0], button: 'Охолодження', cam: [[-L / 2 - 3.5, 2.6, 3.8], [-L / 2, 1.3, 0]] }] : []),
      ...unitsExtra],
    pinOffset: { chiller: chillerOutside ? [-0.1, 0.9, 0] : [0, 1.0, 0.3], ...Object.fromEntries(unitsExtra.map(u => [u.id, [0, u.size[1] / 2 + 0.1, 0.3]])) },
    fire: { items: [
      { type: 'aerosol', pos: [xs0 + 0.5, H - 0.4, 0.6], label: 'Аерозольний генератор', pin: [0, 0.1, 0] },
      { type: 'smoke', pos: [xs0 + 1.0, H - 0.12, 0.62], label: 'Датчик диму', pin: [0, -0.1, 0] },
      { type: 'heat', pos: [xs1 - 1.0, H - 0.12, 0.62], label: 'Датчик температури', pin: [0, -0.1, 0] },
      ...(fireAgent.includes('вода') ? [{ type: 'hpipe', x0: xs0 + 0.2, x1: xs1 - 0.2, pos: [0, H - 0.15, 0.25], nozzles: Array.from({ length: Math.round((xs1 - xs0) / 1.2) }, (_, i) => xs0 + 0.6 + i * 1.2), label: 'Лінія водяного пожежогасіння', pin: [0, 0.12, 0] }, { type: 'gas', pos: [0, H - 0.3, 0.6], label: 'Датчик горючих газів', pin: [0, 0.1, 0] }] : []),
    ], alarmLeds: [] },
    rows: [['door', 'Контейнер і двері'], ['mods', `Батарейні пакети, ${cols * perCol} шт.`], ...rowsExtra, ['chiller', 'Рідинне охолодження'], ['fire', 'Пожежна безпека']],
    info: { door: { name: 'Контейнер і двері', text: 'Контейнер 20 футів, двері обслуговування вздовж довгої сторони, великі літери ZOE на фасаді.', kv: [['Д × Ш × В', `${Math.round(L * 1000)} × ${Math.round(W * 1000)} × ${Math.round(H * 1000)} мм`]] }, mods: { name: 'Батарейні пакети' },
      chiller: { name: 'Рідинне охолодження', short: 'Охолодження', text: 'Рідинне охолодження / підігрів батареї.', kv: [] },
      fire: { name: 'Пожежна безпека', short: 'Пожежогасіння', text: `Гасіння: ${fireAgent}; датчики диму і температури.`, kv: [['Гасіння', fireAgent]] }, ...info },
    notes: { module: 'Кількість пакетів — з даташита; розкладка стійок — схематична.' }, summary,
    cams: { cab: [[L * 0.95, 3.5, 8.8], [0.3, 1.1, 0]], open: [[0.9, 3.1, 8.4], [0.1, 1.15, 0]], exp: [[L * 1.1, 5.6, 10.5], [0, 1.8, 0.8]], fire: [[3.6, 4.6, 7.4], [0, 1.3, 0]] },
    page, meta };
}

